% Median of the filtered displacements towards the magnet (-X component,
% 0.3-8 um) for each sample and position, and mean +/- SD of the medians of
% the three samples for each position (reproducibility and comparison
% between positions).
%
% Input: tp_01.mat files generated by TFMLAB (3 samples x 3 positions).
% The example below corresponds to PEG-W 1.2%; change the paths for PEG-W 1.5%.

clear
clc
close all

%% Input: 3 files per position (edit the paths)
base = 'path/to/data/peg12';
tail = fullfile('D_2_displacements', 'beads', 'tp_01.mat');
posNames = {'pos1 (near magnet)', 'pos2 (middle)', 'pos3 (far from magnet)'};

files = { ...
    { fullfile(base, 'SAMPLE_A_7trials', 'pos1', 'peg12_sample2_trial1_pos1', tail), ...
      fullfile(base, 'SAMPLE_B', 'sample3pos1', tail), ...
      fullfile(base, 'SAMPLE_C', 'sample5pos1', tail) }, ...   % pos1
    { fullfile(base, 'SAMPLE_A_7trials', 'pos2', 'peg12_sample2_trial1_pos2', tail), ...
      fullfile(base, 'SAMPLE_B', 'sample3pos2', tail), ...
      fullfile(base, 'SAMPLE_C', 'sample5pos2', tail) }, ...   % pos2
    { fullfile(base, 'SAMPLE_A_7trials', 'pos3', 'peg12_sample2_trial1_pos3', tail), ...
      fullfile(base, 'SAMPLE_B', 'sample3pos3', tail), ...
      fullfile(base, 'SAMPLE_C', 'sample5pos3', tail) } };     % pos3

%% Filter limits (um, applied to |X|)
minVal = 0.3;
maxVal = 8;

nPos   = numel(files);
nFiles = numel(files{1});

medians       = zeros(nFiles, nPos);   % columns = positions
nKept         = zeros(nFiles, nPos);
meanOfMedians = zeros(1, nPos);
sdOfMedians   = zeros(1, nPos);

%% Process each position
for p = 1:nPos
    fprintf('\n=== %s ===\n', posNames{p})

    for k = 1:nFiles
        fprintf('Processing %s\n', files{p}{k})
        S = load(files{p}{k});
        X = S.dispField.X(:);

        % remove NaNs
        X = X(~isnan(X));

        % keep only the -X component, as positive magnitudes
        X = -X(X < 0);

        % filter step: keep values between minVal and maxVal (um)
        X = X(X >= minVal & X <= maxVal);

        % median of the filtered values (NaN with a warning if nothing is left)
        nKept(k, p) = numel(X);
        if nKept(k, p) == 0
            warning('No points left after filtering: %s', files{p}{k})
            medians(k, p) = NaN;
        else
            medians(k, p) = median(X);
        end
    end

    % mean and SD of the 3 medians of this position
    meanOfMedians(p) = mean(medians(:, p));
    sdOfMedians(p)   = std(medians(:, p));   % sample SD (N-1)
end

%% Results
fprintf('\n--- Results: -X component (um) ---\n')
for p = 1:nPos
    fprintf('\n%s\n', posNames{p})
    for k = 1:nFiles
        fprintf('  File %d: median = %.4f um (N = %d)\n', k, medians(k, p), nKept(k, p))
    end
    fprintf('  Mean of medians = %.4f um\n', meanOfMedians(p))
    fprintf('  SD of medians   = %.4f um\n', sdOfMedians(p))
    fprintf('  Report as: %.2f +/- %.2f um\n', meanOfMedians(p), sdOfMedians(p))
end

%% Summary table
T = table(posNames', meanOfMedians', sdOfMedians', ...
    'VariableNames', {'Position', 'Mean_of_medians_um', 'SD_um'});
disp(T)
